#[summary("Task functions")]
mod tasks {
    #[effects(pure)]
    #[uses(clamped)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires ordered(lo, hi),
        ensures clamped(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn clamped(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        x < lo && r == lo || x > hi && r == hi || lo <= x && x <= hi && r == x
    }

    spec fn ordered(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("tasks")]
mod tasks {
    spec fn is_floor_mid(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_floor_mid)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_floor_mid(a, b, r),
    {
        let ma: i64 = a % 2;
        let mb: i64 = b % 2;
        let fa: i64 = if ma < 0 {
            a / 2 - 1
        } else {
            a / 2
        };
        let fb: i64 = if mb < 0 {
            b / 2 - 1
        } else {
            b / 2
        };
        let ra: i64 = a - 2 * fa;
        let rb: i64 = b - 2 * fb;
        fa + fb + (ra + rb) / 2
    }
}

#[summary("saturating sum")]
mod tasks {
    spec fn inv(a: &[i64], i: usize, s: i64) -> bool {
        i <= a.len() && s == sat_prefix(a, i)
    }

    spec fn is_sat_sum(a: &[i64], r: i64) -> bool {
        r == sat_prefix(a, a.len())
    }

    #[effects(pure)]
    #[uses(sat_add_ok, sat_add_spec)]
    fn sat_add(p: i64, x: i64) -> (r: i64)
        ensures sat_add_ok(p, x, r),
    {
        if x >= 0 {
            if p > i64::MAX - x {
                i64::MAX
            } else {
                p + x
            }
        } else {
            if p < i64::MIN - x {
                i64::MIN
            } else {
                p + x
            }
        }
    }

    spec fn sat_add_ok(p: i64, x: i64, r: i64) -> bool {
        r == sat_add_spec(p, x)
    }

    spec fn sat_add_spec(p: i64, x: i64) -> i64 {
        if p + x > i64::MAX {
            i64::MAX
        } else if p + x < i64::MIN {
            i64::MIN
        } else {
            p + x
        }
    }

    #[uses(sat_add_spec)]
    spec fn sat_prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            sat_add_spec(sat_prefix(a, n - 1), a[n - 1])
        }
    }

    #[effects(pure)]
    #[uses(inv, is_sat_sum, sat_add_ok, sat_prefix)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures is_sat_sum(a, r),
    {
        let mut i: usize = 0;
        let mut s: i64 = 0;
        while i < a.len()
            invariant inv(a, i, s),
            decreases a.len() - i,
        {
            s = sat_add(s, a[i]);
            i = i + 1;
        }
        s
    }
}

#[summary("counting tasks")]
mod tasks {
    #[effects(pure)]
    #[uses(count_prefix, inv, is_count)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures is_count(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant inv(a, lo, hi, i, c),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    spec fn count_prefix(a: &[i64], n: usize, lo: i64, hi: i64) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else if lo <= a[n - 1] && a[n - 1] <= hi {
            count_prefix(a, n - 1, lo, hi) + 1
        } else {
            count_prefix(a, n - 1, lo, hi)
        }
    }

    spec fn inv(a: &[i64], lo: i64, hi: i64, i: usize, c: usize) -> bool {
        i <= a.len() && c <= i && c == count_prefix(a, i, lo, hi)
    }

    spec fn is_count(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == count_prefix(a, a.len(), lo, hi)
    }
}

#[summary("Array tasks")]
mod tasks {
    #[effects(pure)]
    #[uses(is_first_max, loop_inv, nonempty)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_first_max(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant loop_inv(a, i, best),
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r])
    }

    spec fn loop_inv(a: &[i64], i: usize, best: usize) -> bool {
        best < i && i <= a.len() && (forall|j: usize| j < i ==> #[trigger] a[j] <= a[best]) && (forall|k: usize| k < best ==> #[trigger] a[k] < a[best])
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("Tasks")]
mod tasks {
    spec fn inv(a: &[i64], idx: usize, i: usize) -> bool {
        idx < i && i <= a.len() && (forall|j: usize| j < i ==> a[idx] <= #[trigger] a[j]) && (forall|k: usize| idx < k && k < i ==> a[idx] < #[trigger] a[k])
    }

    spec fn is_last_min(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> a[r] <= #[trigger] a[j]) && (forall|k: usize| r < k && k < a.len() ==> a[r] < #[trigger] a[k])
    }

    #[effects(pure)]
    #[uses(inv, is_last_min, nonempty)]
    fn last_min_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_last_min(a, r),
    {
        let mut idx: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant inv(a, idx, i),
            decreases a.len() - i,
        {
            if a[i] <= a[idx] {
                idx = i;
            }
            i = i + 1;
        }
        idx
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("tasks")]
mod tasks {
    spec fn inc(a: &[i64], n: usize) -> bool {
        forall|j: usize| j + 1 < n && n <= a.len() ==> #[trigger] a[j] < a[j + 1]
    }

    spec fn res_ok(a: &[i64], r: bool) -> bool {
        r == inc(a, a.len())
    }

    spec fn state_ok(a: &[i64], i: usize, ok: bool) -> bool {
        i <= a.len() && (ok ==> inc(a, i)) && (!ok ==> !inc(a, a.len()))
    }

    #[effects(pure)]
    #[uses(inc, res_ok, state_ok)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures res_ok(a, r),
    {
        let mut i: usize = 0;
        let mut ok: bool = true;
        while ok && i < a.len()
            invariant state_ok(a, i, ok),
            decreases a.len() - i + (if ok { 1 } else { 0 }),
        {
            if i >= 1 && a[i - 1] >= a[i] {
                ok = false;
            } else {
                i = i + 1;
            }
        }
        ok
    }
}

#[summary("binary search tasks")]
mod tasks {
    spec fn at_ge(a: &[i64], t: i64, r: usize) -> bool {
        r == a.len() || r < a.len() && a[r] >= t
    }

    spec fn below_lt(a: &[i64], t: i64, r: usize) -> bool {
        r <= a.len() && (forall|k: usize| k < r ==> #[trigger] a[k] < t)
    }

    spec fn bounds(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    #[effects(pure)]
    #[uses(at_ge, below_lt, bounds, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures below_lt(a, t, r), at_ge(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant bounds(a, lo, hi), below_lt(a, t, lo), at_ge(a, t, hi), sorted(a),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }
}

#[summary("floor division")]
mod tasks {
    #[effects(pure)]
    #[uses(div_ok, is_floor)]
    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires div_ok(a, b),
        ensures is_floor(a, b, r),
    {
        let q: i64 = a / b;
        let m: i64 = a % b;
        if m != 0 && (m < 0) != (b < 0) {
            q - 1
        } else {
            q
        }
    }

    spec fn div_ok(a: i64, b: i64) -> bool {
        b != 0 && !(a == -9223372036854775807 - 1 && b == -1)
    }

    spec fn is_floor(a: i64, b: i64, r: i64) -> bool {
        if b > 0 {
            r * b <= a && a < r * b + b
        } else {
            r * b >= a && a > r * b + b
        }
    }
}

#[summary("floor-division remainder")]
mod tasks {
    spec fn is_mod_floor(a: i64, b: i64, r: i64) -> bool {
        (a - r) % b == 0 && (b > 0 ==> 0 <= r && r < b) && (b < 0 ==> b < r && r <= 0)
    }

    #[effects(pure)]
    #[uses(is_mod_floor, nonzero)]
    fn mod_floor(a: i64, b: i64) -> (r: i64)
        requires nonzero(b),
        ensures is_mod_floor(a, b, r),
    {
        if b == -1 {
            0
        } else {
            let m: i64 = a % b;
            if m != 0 && b > 0 && m < 0 {
                m + b
            } else if m != 0 && b < 0 && m > 0 {
                m + b
            } else {
                m
            }
        }
    }

    spec fn nonzero(b: i64) -> bool {
        b != 0
    }
}

#[summary("max subarray sum")]
mod tasks {
    spec fn all_best(a: &[i64], k: usize, bs: usize, be: usize, b: i64) -> bool {
        k <= a.len() && bs < be && be <= k && sum(a, bs, be) == b && (forall|i: usize, j: usize| i < j && j <= k ==> #[trigger] sum(a, i, j) <= b)
    }

    spec fn bounds(c: i64, b: i64, k: usize) -> bool {
        -1000000000 <= c && c <= 1000000000 * k && -1000000000 <= b && b <= 1000000000 * k
    }

    spec fn dom(a: &[i64]) -> bool {
        a.len() >= 1 && a.len() <= 1000000 && (forall|i: usize| i < a.len() ==> -1000000000 <= #[trigger] a[i] && a[i] <= 1000000000)
    }

    spec fn ends_best(a: &[i64], k: usize, s: usize, c: i64) -> bool {
        k <= a.len() && s < k && sum(a, s, k) == c && (forall|i: usize| i < k ==> #[trigger] sum(a, i, k) <= c)
    }

    spec fn is_max(a: &[i64], r: i64) -> bool {
        (forall|i: usize, j: usize| i < j && j <= a.len() ==> #[trigger] sum(a, i, j) <= r) && !(forall|p: usize, q: usize| p < q && q <= a.len() ==> #[trigger] sum(a, p, q) != r)
    }

    #[effects(pure)]
    #[uses(all_best, bounds, dom, ends_best, is_max, sum)]
    fn max_subarray(a: &[i64]) -> (r: i64)
        requires dom(a),
        ensures is_max(a, r),
    {
        let mut cur: i64 = a[0];
        let mut best: i64 = a[0];
        let mut s: usize = 0;
        let mut bs: usize = 0;
        let mut be: usize = 1;
        let mut k: usize = 1;
        while k < a.len()
            invariant dom(a), 1 <= k, k <= a.len(), ends_best(a, k, s, cur), all_best(a, k, bs, be, best), bounds(cur, best, k),
            decreases a.len() - k,
        {
            if cur > 0 {
                cur = cur + a[k];
            } else {
                cur = a[k];
                s = k;
            }
            if cur > best {
                best = cur;
                bs = s;
                be = k + 1;
            }
            k = k + 1;
        }
        best
    }

    spec fn sum(a: &[i64], i: usize, j: usize) -> i64
        decreases j,
    {
        if j <= i {
            0
        } else {
            sum(a, i, j - 1) + a[j - 1]
        }
    }
}

#[summary("second largest distinct value")]
mod tasks {
    spec fn absent(a: &[i64], v: i64, n: usize) -> bool {
        n <= a.len() && (forall|k: usize| k < n ==> #[trigger] a[k] != v)
    }

    spec fn below_le(a: &[i64], m: i64, s: i64, n: usize) -> bool {
        n <= a.len() && (forall|i: usize| i < n ==> #[trigger] a[i] < m ==> a[i] <= s)
    }

    spec fn bounded(a: &[i64], m: i64, n: usize) -> bool {
        n <= a.len() && (forall|i: usize| i < n ==> #[trigger] a[i] <= m)
    }

    spec fn no_greater(a: &[i64], v: i64) -> bool {
        forall|j: usize| j < a.len() ==> #[trigger] a[j] <= v
    }

    spec fn post(a: &[i64], r: i64) -> bool {
        (r == i64::MIN || !absent(a, r, a.len()) && !no_greater(a, r)) && (forall|i: usize, j: usize| i < a.len() && j < a.len() && #[trigger] a[i] < #[trigger] a[j] ==> a[i] <= r)
    }

    #[effects(pure)]
    #[uses(absent, below_le, bounded, no_greater, post)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures post(a, r),
    {
        if a.len() == 0 {
            i64::MIN
        } else {
            let mut m: i64 = a[0];
            let mut s: i64 = i64::MIN;
            let mut i: usize = 1;
            while i < a.len()
                invariant 1 <= i, i <= a.len(), bounded(a, m, i), !absent(a, m, i), below_le(a, m, s, i), s <= m, s == i64::MIN || s < m && !absent(a, s, i),
                decreases a.len() - i,
            {
                let x: i64 = a[i];
                if x > m {
                    s = m;
                    m = x;
                } else if x < m && x > s {
                    s = x;
                }
                i = i + 1;
            }
            s
        }
    }
}

#[summary("rotate a slice right in place")]
mod tasks {
    spec fn m_ok(a: &[i64], m: usize) -> bool {
        m < a.len()
    }

    spec fn rev_inv(a: &[i64], o: &[i64], lo: usize, hi: usize, l: usize, r: usize) -> bool {
        a.len() == o.len() && lo <= l && l <= r && r <= hi && hi <= a.len() && l + r == lo + hi && (forall|i: usize| i < a.len() ==> (i < lo || i >= hi ==> #[trigger] a[i] == o[i]) && (lo <= i && i < l || r <= i && i < hi ==> a[i] == o[lo + hi - 1 - i]) && (l <= i && i < r ==> a[i] == o[i]))
    }

    spec fn rev_post(a: &[i64], o: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == o.len() && (forall|i: usize| i < a.len() ==> (i < lo || i >= hi ==> #[trigger] a[i] == o[i]) && (lo <= i && i < hi ==> a[i] == o[lo + hi - 1 - i]))
    }

    spec fn rev_range_ok(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    #[effects(pure)]
    #[uses(rev_inv, rev_post, rev_range_ok)]
    fn reverse_range(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires rev_range_ok(a, lo, hi),
        ensures rev_post(a, old(a), lo, hi),
    {
        let mut l: usize = lo;
        let mut r: usize = hi;
        while l + 1 < r
            invariant rev_inv(a, old(a), lo, hi, l, r),
            decreases r - l,
        {
            let x: i64 = a[l];
            let y: i64 = a[r - 1];
            a[l] = y;
            a[r - 1] = x;
            l = l + 1;
            r = r - 1;
        }
    }

    spec fn rot_mid(a: &[i64], o: &[i64], m: usize) -> bool {
        a.len() == o.len() && m < a.len() && (forall|i: usize| i < o.len() ==> (i + m < o.len() ==> #[trigger] a[i + m] == o[i]) && (i + m >= o.len() ==> a[i + m - o.len()] == o[i]))
    }

    spec fn rot_post(a: &[i64], o: &[i64], k: usize) -> bool {
        a.len() == o.len() && (forall|i: usize| i < o.len() ==> (i + k % o.len() < o.len() ==> #[trigger] a[i + k % o.len()] == o[i]) && (i + k % o.len() >= o.len() ==> a[i + k % o.len() - o.len()] == o[i]))
    }

    #[effects(pure)]
    #[uses(m_ok, rot_mid, rot_post)]
    fn rotate_right(a: &mut [i64], k: usize) -> ()
        ensures rot_post(a, old(a), k),
    {
        let n: usize = a.len();
        if n > 0 {
            let m: usize = k % n;
            tasks::rotate_small(a, m);
        }
    }

    #[effects(pure)]
    #[uses(m_ok, rev_post, rev_range_ok, rot_mid)]
    fn rotate_small(a: &mut [i64], m: usize) -> ()
        requires m_ok(a, m),
        ensures rot_mid(a, old(a), m),
    {
        let n: usize = a.len();
        tasks::reverse_range(a, 0, n);
        tasks::reverse_range(a, 0, m);
        tasks::reverse_range(a, m, n);
    }
}

#[summary("Sorted-slice tasks")]
mod tasks {
    spec fn bound_ok(a: &[i64], r: usize) -> bool {
        r <= a.len()
    }

    spec fn covered(b: &[i64], a: &[i64], k: usize, w: usize) -> bool {
        forall|i: usize| i < k && k <= b.len() && w <= a.len() ==> has_val(a, w, #[trigger] b[i])
    }

    #[effects(pure)]
    #[uses(bound_ok, covered, has_val, last_ok, same_from, sorted, sourced, strict_prefix, zeros_from, zeros_from_range)]
    fn dedup_sorted(a: &mut [i64]) -> (r: usize)
        requires sorted(a),
        ensures bound_ok(a, r), strict_prefix(a, r), zeros_from(a, r), covered(old(a), a, old(a).len(), r), sourced(a, old(a), r, old(a).len()),
    {
        let n: usize = a.len();
        let mut w: usize = 0;
        let mut i: usize = 0;
        while i < n
            invariant w <= i, i <= n, n == a.len(), sorted(old(a)), strict_prefix(a, w), same_from(a, old(a), i), covered(old(a), a, i, w), sourced(a, old(a), w, i), last_ok(a, old(a), i, w), zeros_from_range(a, w, i),
            decreases n - i,
        {
            let v: i64 = a[i];
            if w > 0 && a[w - 1] == v {
                a[i] = 0;
            } else {
                if w < i {
                    a[i] = 0;
                }
                a[w] = v;
                w = w + 1;
            }
            i = i + 1;
        }
        w
    }

    spec fn has_val(a: &[i64], w: usize, v: i64) -> bool
        decreases w,
    {
        w <= a.len() && w > 0 && (a[w - 1] == v || has_val(a, w - 1, v))
    }

    spec fn last_ok(a: &[i64], b: &[i64], i: usize, w: usize) -> bool {
        i == 0 && w == 0 || i > 0 && w > 0 && w <= i && i <= a.len() && a.len() == b.len() && a[w - 1] == b[i - 1]
    }

    spec fn same_from(a: &[i64], b: &[i64], i: usize) -> bool {
        a.len() == b.len() && (forall|k: usize| i <= k && k < a.len() ==> #[trigger] a[k] == b[k])
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }

    spec fn sourced(a: &[i64], b: &[i64], w: usize, k: usize) -> bool {
        forall|j: usize| j < w && w <= a.len() && k <= b.len() ==> has_val(b, k, #[trigger] a[j])
    }

    spec fn strict_prefix(a: &[i64], w: usize) -> bool {
        forall|i: usize, j: usize| i < j && j < w && w <= a.len() ==> #[trigger] a[i] < #[trigger] a[j]
    }

    spec fn zeros_from(a: &[i64], w: usize) -> bool {
        forall|i: usize| w <= i && i < a.len() ==> #[trigger] a[i] == 0
    }

    spec fn zeros_from_range(a: &[i64], w: usize, j: usize) -> bool {
        forall|i: usize| w <= i && i < j && j <= a.len() ==> #[trigger] a[i] == 0
    }
}

#[summary("array tasks")]
mod tasks {
    spec fn count_nz(a: &[i64], n: usize) -> usize
        decreases n,
    {
        if n == 0 {
            0
        } else if a[n - 1] != 0 {
            count_nz(a, n - 1) + 1
        } else {
            count_nz(a, n - 1)
        }
    }

    #[effects(pure)]
